/// <reference types="@sveltejs/kit" />
import { build, files, version } from '$service-worker';

const CACHE = `docs-pwa-cache-${version}`;

// Assets generated by Vite/SvelteKit + static files
const PRECACHE_ASSETS = [
	...build,
	...files.filter(
		(f) =>
			!f.startsWith('/uploads/') && // Do not precache dynamic user image uploads
			!f.endsWith('.map')
	)
];

self.addEventListener('install', (event: any) => {
	event.waitUntil(
		caches
			.open(CACHE)
			.then((cache) => cache.addAll(PRECACHE_ASSETS))
			.then(() => (self as any).skipWaiting())
	);
});

self.addEventListener('activate', (event: any) => {
	event.waitUntil(
		caches.keys().then(async (keys) => {
			for (const key of keys) {
				if (key !== CACHE) {
					await caches.delete(key);
				}
			}
			await (self as any).clients.claim();
		})
	);
});

self.addEventListener('fetch', (event: any) => {
	const req = event.request;
	if (req.method !== 'GET') return;

	const url = new URL(req.url);

	// Only handle same-origin requests or local assets
	if (url.origin !== location.origin) return;

	// Ignore API routes, AI endpoints, and internal sveltekit live sync
	if (
		url.pathname.startsWith('/api/') ||
		url.pathname.startsWith('/__') ||
		url.pathname.includes('/_app/env')
	) {
		return;
	}

	event.respondWith(
		(async () => {
			const cache = await caches.open(CACHE);

			// 1. If it's a precached static asset or build file, serve from cache first
			if (PRECACHE_ASSETS.includes(url.pathname)) {
				const cachedResponse = await cache.match(req);
				if (cachedResponse) return cachedResponse;
			}

			// 2. Network-first strategy with cache fallback for pages and content
			try {
				const response = await fetch(req);
				if (response && response.status === 200 && response.type === 'basic') {
					// Cache the fresh response in the background
					cache.put(req, response.clone());
				}
				return response;
			} catch (err) {
				// If offline or network error, serve from cache
				const cachedResponse = await cache.match(req);
				if (cachedResponse) return cachedResponse;

				// If looking for a document page while offline, return cached root or fallback
				if (req.headers.get('accept')?.includes('text/html')) {
					const rootCached = await cache.match('/');
					if (rootCached) return rootCached;
				}

				throw err;
			}
		})()
	);
});
